CREATE TYPE "PrivacyRequestType" AS ENUM('EXPORT','CORRECTION','DELETION','CONSENT_WITHDRAWAL');CREATE TYPE "PrivacyRequestStatus" AS ENUM('OPEN','VERIFYING','PROCESSING','COMPLETED','REJECTED');
CREATE TABLE "privacy_requests"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL REFERENCES "app_users"("id") ON DELETE RESTRICT,"type" "PrivacyRequestType" NOT NULL,"status" "PrivacyRequestStatus" NOT NULL DEFAULT 'OPEN',"details" varchar(2000),"resolution" varchar(2000),"export_object_path" varchar(700),"verified_at" timestamptz(6),"completed_at" timestamptz(6),"created_at" timestamptz(6) NOT NULL DEFAULT now(),"updated_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "privacy_requests_user_id_status_created_at_idx" ON "privacy_requests"("user_id","status","created_at");CREATE INDEX "privacy_requests_status_type_created_at_idx" ON "privacy_requests"("status","type","created_at");
CREATE TABLE "analytics_events"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" varchar(80) NOT NULL,"anonymous_session_hash" varchar(64) NOT NULL,"properties" jsonb NOT NULL DEFAULT '{}',"schema_version" int NOT NULL DEFAULT 1,"occurred_at" timestamptz(6) NOT NULL,"received_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "analytics_events_name_occurred_at_idx" ON "analytics_events"("name","occurred_at");
CREATE TABLE "retention_executions"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"job_name" varchar(80) NOT NULL,"deleted_rows" int NOT NULL DEFAULT 0,"status" varchar(20) NOT NULL,"error" varchar(1000),"started_at" timestamptz(6) NOT NULL DEFAULT now(),"finished_at" timestamptz(6));CREATE INDEX "retention_executions_job_name_started_at_idx" ON "retention_executions"("job_name","started_at");
INSERT INTO "permissions"("code","description")VALUES('privacy.manage','Process privacy rights requests'),('analytics.read','Read aggregate platform analytics')ON CONFLICT("code")DO NOTHING;INSERT INTO "role_permissions"("role_id","permission_id")SELECT r.id,p.id FROM "roles" r CROSS JOIN "permissions" p WHERE r.code='SUPER_ADMIN'AND p.code IN('privacy.manage','analytics.read')ON CONFLICT DO NOTHING;
ALTER TABLE "privacy_requests" ENABLE ROW LEVEL SECURITY;ALTER TABLE "analytics_events" ENABLE ROW LEVEL SECURITY;ALTER TABLE "retention_executions" ENABLE ROW LEVEL SECURITY;REVOKE ALL ON "privacy_requests","analytics_events","retention_executions" FROM anon,authenticated;
